        c = new C();
    }

    function testFuzz_property(address newOwner, address callerAfter) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != deployer);
        vm.assume(callerAfter != deployer);
        vm.assume(callerAfter != address(0));

